'use strict';
const BASE_CLASSES={warrior:{name:'นักรบ',main:'str',weapons:['sword','spear','axe','hammer'],ratings:[4,4,5]},shooter:{name:'นักยิง',main:'dex',weapons:['bow','crossbow','gun'],ratings:[3,4,3]},mage:{name:'นักเวท',main:'int',weapons:['wand','staff','tome'],ratings:[5,3,2]},rogue:{name:'นักลอบโจมตี',main:'luk',weapons:['dagger','claw','star'],ratings:[3,3,3]}};
const WEAPON_NAMES={sword:'ดาบ',spear:'หอก',axe:'ขวาน',hammer:'ค้อน',bow:'ธนู',crossbow:'หน้าไม้',gun:'ปืน',wand:'คทา',staff:'ไม้เท้า',tome:'หนังสือเวท',dagger:'มีด',claw:'กรงเล็บ',star:'ดาวกระจาย'};
const SKILL_MIN_LEVEL=[0,10,30,60,100],SKILL_KINDS={active:'Active',buff:'Buff',passive:'Passive'};
const WEAPON_SKILLS={};for(const [weapon,name]of Object.entries(WEAPON_NAMES))for(let tier=1;tier<=4;tier++)for(const [kind,names]of Object.entries({active:['โจมตี'],buff:['เสริมพลัง','เกราะคุ้มกัน'],passive:['เชี่ยวชาญ','คล่องตัว']}))names.forEach((suffix,index)=>{const id=weapon+'_'+tier+'_'+kind+'_'+index;WEAPON_SKILLS[id]={id,weapon,tier,kind,name:name+' · '+suffix+' ขั้น '+tier,index}});
function emptyWeaponLoadout(){return Array.from({length:4},()=>({active:[null],buff:[null,null],passive:[null,null]}))}
function validClass(p=player){return BASE_CLASSES[p.baseClass]||BASE_CLASSES.warrior}
function weaponInHand(hand,p=player){const g=p.loot.gear.find(g=>g.id===p.loot.equipped[hand]);if(g)return g.weapon||'sword';return hand==='main'?validClass(p).weapons[0]:null}
function weaponSkillEnabled(id,p=player){const d=WEAPON_SKILLS[id];return !!d&&(p.weaponSkills?.[id]||0)>0&&p.level>=SKILL_MIN_LEVEL[d.tier]&&validClass(p).weapons.includes(d.weapon)&&(weaponInHand('main',p)===d.weapon||(d.kind!=='active'&&weaponInHand('secondary',p)===d.weapon))}
function upgradeWeaponChance(target){return target<=5?100:target<=10?80:target<=15?65:target<=20?50:target<=25?40:30}
function weaponSkillText(id){const d=WEAPON_SKILLS[id],lv=player.weaponSkills[id]||0;if(d.kind==='active')return 'ใช้ '+WEAPON_NAMES[d.weapon]+' มือหลัก · '+(100+d.tier*20+lv*3)+'% ATK · MP '+(5+d.tier*3)+' · '+(d.tier>1?'คูลดาวน์ '+(d.tier*2)+' วิ':'พักท่า 0.4 วิ');if(d.kind==='buff')return 'ใช้ '+WEAPON_NAMES[d.weapon]+' มือหลักหรือรอง · '+(d.index===0?'ATK +'+(d.tier*2+lv):'DEF +'+(d.tier*2+lv))+' · 120 วินาที · MP 8';return 'ใช้ '+WEAPON_NAMES[d.weapon]+' มือหลักหรือรอง · '+(d.index===0?'ATK +'+(d.tier+lv):'SPD +'+Math.min(20,d.tier+lv)+'%');}
function validateWeaponSystem(raw,p){p.baseClass=raw.baseClass||(['mage','rogue','shooter'].includes(raw.job)?raw.job:'warrior');if(!BASE_CLASSES[p.baseClass])throw Error('อาชีพหลักไม่ถูกต้อง');p.job=p.baseClass;p.weaponSkills={};p.skillScrolls={};for(const [field,max]of [['weaponSkills',30],['skillScrolls',999999]]){const data=raw[field]||{};if(typeof data!=='object'||Array.isArray(data))throw Error('กระเป๋าสกิลไม่ถูกต้อง');for(const [id,n]of Object.entries(data)){if(!WEAPON_SKILLS[id]||!Number.isInteger(n)||n<0||n>max)throw Error('สกิลอาวุธไม่ถูกต้อง');if(n)p[field][id]=n}}p.weaponLoadout=emptyWeaponLoadout();if(raw.weaponLoadout!==undefined){if(!Array.isArray(raw.weaponLoadout)||raw.weaponLoadout.length!==4)throw Error('ช่องสกิลไม่ถูกต้อง');for(let i=0;i<4;i++)for(const kind of Object.keys(SKILL_KINDS)){const row=raw.weaponLoadout[i][kind];if(!Array.isArray(row)||row.length!==(kind==='active'?1:2))throw Error('ช่องสกิลไม่ถูกต้อง');for(let j=0;j<row.length;j++){const id=row[j];if(id!==null&&(!WEAPON_SKILLS[id]||WEAPON_SKILLS[id].tier!==i+1||WEAPON_SKILLS[id].kind!==kind||!p.weaponSkills[id]))throw Error('สกิลในช่องไม่ถูกต้อง');p.weaponLoadout[i][kind][j]=id}if(new Set(row.filter(Boolean)).size!==row.filter(Boolean).length)throw Error('สกิลซ้ำในขั้น')}}p.legacySkillBuild=raw.legacySkillBuild||(!raw.baseClass?{job:raw.job,sp:raw.sp,secondSP:raw.secondSP,swordSkills:raw.swordSkills,secondSkills:raw.secondSkills}:null);if(!raw.baseClass){const weapon=raw.job==='spearman'?'spear':'sword';for(const [tier,data]of [[1,raw.swordSkills||{}],[2,raw.secondSkills||{}]]){const count=Object.values(data).filter(n=>n>0).length;if(count){const id=weapon+'_'+tier+'_active_0';p.skillScrolls[id]=(p.skillScrolls[id]||0)+count}}}for(const g of p.loot.gear)if(['main','secondary'].includes(g.slot)&&!g.weapon)g.weapon=raw.job==='spearman'?'spear':'sword';p.sp=0;p.secondSP=0;p.swordSkills=emptySwordSkills();p.secondSkills={};p.skillSlots={q:null,w:null,e:null,r:null};p.promotionTokens=0;p.questState='completed';}
function weaponLoadoutBonuses(p=player){const out={atk:0,def:0,spd:0};const seen=new Set();for(const row of p.weaponLoadout||[])for(const kind of ['buff','passive'])for(const id of row[kind]){if(!id||seen.has(id)||!weaponSkillEnabled(id,p))continue;seen.add(id);const d=WEAPON_SKILLS[id],lv=p.weaponSkills[id];if(kind==='buff'){if(!(p.weaponBuffs?.[id]>0))continue;out[d.index===0?'atk':'def']+=d.tier*2+lv}else out[d.index===0?'atk':'spd']+=d.index===0?d.tier+lv:Math.min(20,d.tier+lv)}return out}
function learnOrUpgradeWeaponSkill(id){const d=WEAPON_SKILLS[id],lv=player.weaponSkills[id]||0;if(!d||!player.skillScrolls[id]||lv>=30)return false;player.skillScrolls[id]--;if(!player.skillScrolls[id])delete player.skillScrolls[id];const success=lv===0||Math.random()*100<upgradeWeaponChance(lv+1);if(success)player.weaponSkills[id]=lv+1;save();toast(success?'สำเร็จ · '+d.name+' Lv.'+player.weaponSkills[id]:'อัปไม่สำเร็จ · เลเวลเดิมยังอยู่');return success}
function rollSkillScroll(tier){const pool=Object.values(WEAPON_SKILLS).filter(s=>s.tier===tier);return pool[Math.floor(Math.random()*pool.length)].id}
function castWeaponSkill(id){const d=WEAPON_SKILLS[id];if(paused||screen!=='play'||run?.finished||!weaponSkillEnabled(id))return false;if((player.cd.action||0)>0)return queueAction(id);if((player.cd[id]||0)>0)return false;const cost=d.kind==='buff'?8:5+d.tier*3;if(player.mp<cost||d.kind==='passive')return false;player.mp-=cost;beginActionDelay('slashBlast');if(d.kind==='buff'){player.weaponBuffs??={};player.weaponBuffs[id]=120;save();updateUI();return true}player.cd[id]=d.tier===1?0:d.tier*2;const lv=player.weaponSkills[id],power=attackPower()*(1+d.tier*.2+lv*.03),ranged=['bow','crossbow','gun','wand','staff','tome','star'].includes(d.weapon);if(ranged){let dx=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0),dy=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0);if(!dx&&!dy)dx=player.face;const len=Math.hypot(dx,dy);swordWaves.push({x:player.x,y:player.y-22,vx:dx/len*560,vy:dy/len*560,life:1.1,damage:power,seen:new Set(),targets:['staff','tome'].includes(d.weapon)?6:3})}else{const reach=d.weapon==='spear'?185:130,targets=d.weapon==='dagger'||d.weapon==='claw'?3:6;for(const m of skillTargets('slashBlast',reach,targets)){hitMonster(m,power);if(d.weapon==='hammer'&&!m.boss&&!m.elite)m.stun=.7} swordSwipes.push({x:player.x,y:player.y-20,face:player.face,reach,life:.3,key:id})}tutorialMark('attack');tone(440,.12,'triangle');updateUI();return true}
function useLoadoutBuff(id){closeModal();if(!$('characterOverlay').hidden)closeCharacterWindow();if(!castWeaponSkill(id))toast('ใช้บัฟไม่ได้ · ตรวจอาวุธ MP และช่วงพักท่า')}
function openWeaponSkillDetail(id){const d=WEAPON_SKILLS[id],lv=player.weaponSkills[id]||0;modal(d.name+' · Lv.'+lv+'/30',weaponSkillText(id)+'\nมีสกิลซ้ำ '+(player.skillScrolls[id]||0)+' ชิ้น\n'+(lv?lv>=30?'ระดับสูงสุดแล้ว':'อัปเป็น Lv.'+(lv+1)+' โอกาส '+upgradeWeaponChance(lv+1)+'%':'เรียนครั้งแรกสำเร็จ 100%'),[['เรียน / อัปด้วยสกิลซ้ำ',()=>{learnOrUpgradeWeaponSkill(id);openWeaponSkillDetail(id)},true],...(d.kind==='buff'&&weaponSkillEnabled(id)?[['ใช้บัฟ',()=>useLoadoutBuff(id)]]:[])]);$('modalButtons').firstElementChild.disabled=lv>=30||!(player.skillScrolls[id]>0)}
function pickWeaponSkill(tier,kind,index){const box=document.createElement('div');box.className='weapon-picker';for(const d of Object.values(WEAPON_SKILLS).filter(d=>d.tier===tier&&d.kind===kind&&player.weaponSkills[d.id])){const b=document.createElement('button');b.textContent=d.name+' Lv.'+player.weaponSkills[d.id]+(weaponSkillEnabled(d.id)?'':' · อาวุธไม่ตรง');b.onclick=()=>{const row=player.weaponLoadout[tier-1][kind];if(row.includes(d.id)){toast('สกิลนี้อยู่ในช่องขั้นนี้แล้ว');return}row[index]=d.id;save();closeModal();openControlWindow('skill')};box.append(b)}modal('เลือก '+kind+' ขั้น '+tier,box,[['ถอดสกิล',()=>{player.weaponLoadout[tier-1][kind][index]=null;save();closeModal();openControlWindow('skill')}],['กระเป๋าสกิล',()=>{closeModal();openCharacterWindow('skills')}]])}
function renderSwordSkillWindow(body){body.className='weapon-skill-window';body.replaceChildren();$('modalTitle').textContent='ชุดสกิลอาวุธ';const close=document.createElement('button');close.id='closeSkillBtn';close.className='window-close';close.textContent='×';close.onclick=closeModal;body.append(close);const grid=document.createElement('div');grid.className='weapon-skill-grid';for(const text of ['ขั้น','Active','Buff','Passive']){const h=document.createElement('strong');h.textContent=text;grid.append(h)}for(let tier=1;tier<=4;tier++){const label=document.createElement('strong');label.textContent=tier+' · Lv.'+SKILL_MIN_LEVEL[tier];grid.append(label);for(const kind of ['active','buff','passive']){const cells=document.createElement('div');cells.className='weapon-slot-group';player.weaponLoadout[tier-1][kind].forEach((id,index)=>{const b=document.createElement('button');b.className='weapon-skill-cell';b.disabled=player.level<SKILL_MIN_LEVEL[tier];b.textContent=id?WEAPON_SKILLS[id].name+'\nLv.'+player.weaponSkills[id]+(weaponSkillEnabled(id)?'':'\nอาวุธไม่ตรง'):'เลือกสกิล';b.onclick=()=>pickWeaponSkill(tier,kind,index);b.onmouseenter=()=>id&&showItemDetail(b,{name:WEAPON_SKILLS[id].name,description:weaponSkillText(id)});cells.append(b);if(id){const detail=document.createElement('button');detail.textContent=kind==='buff'?'ใช้ / อัป':'อัป';detail.className='skill-detail-action';detail.onclick=()=>openWeaponSkillDetail(id);cells.append(detail)}});grid.append(cells)}}body.append(grid);const note=document.createElement('p');note.textContent='Q/W/E/R = Active ขั้น 1/2/3/4 · มือหลักใช้ Active · ทั้งสองมือใช้ Buff/Passive · สกิลซ้ำอัปได้ถึง Lv.30';body.append(note)}
function renderSkillBag(){const grid=$('inventoryGrid');grid.replaceChildren();for(const [id,count]of Object.entries(player.skillScrolls)){const d=WEAPON_SKILLS[id],b=document.createElement('button');b.className='inventory-cell inventory-item skill-scroll';b.textContent=d.name+'\n'+SKILL_KINDS[d.kind]+' ×'+count;b.onclick=()=>openWeaponSkillDetail(id);grid.append(b)}if(!grid.children.length){const empty=document.createElement('p');empty.textContent='ยังไม่มีสกิล · เปิดกล่องสุ่มสกิลเพื่อรับ';grid.append(empty)}}
function updateWeaponHUD(){for(const [i,key]of ['q','w','e','r'].entries()){const id=player.weaponLoadout?.[i]?.active[0],button=$('hotbar'+key.toUpperCase());if(!button)continue;player.skillSlots[key]=id;button.disabled=!id||!weaponSkillEnabled(id)||(player.cd[id]||0)>0;button.querySelector('span').textContent=key.toUpperCase()+'['+(id?WEAPON_SKILLS[id].name:'ว่าง')+']'+((player.cd[id]||0)>0?' '+player.cd[id].toFixed(1)+'s':'');button.title=id?weaponSkillText(id):'เลือก Active ขั้น '+(i+1)}const hud=$('buffHUD');hud.replaceChildren();for(const [id,left]of Object.entries(player.weaponBuffs||{})){if(left<=0||!weaponSkillEnabled(id))continue;const cell=document.createElement('div');cell.className='buff-placeholder';cell.title=WEAPON_SKILLS[id].name+' '+Math.ceil(left)+' วิ';const time=document.createElement('b');time.textContent=Math.ceil(left);cell.append(time);hud.append(cell)}}

function updateBuffHUD(){}
